from __future__ import annotations

from typing import Any, Dict, List, Optional, cast

from rasa.shared.nlu.constants import (
    COMMANDS,
    ENTITIES,
    INTENT,
    INTENT_NAME_KEY,
    PREDICTED_CONFIDENCE_KEY,
    TEXT,
)


def build_parse_data(
    text: str,
    *,
    commands: Optional[List[Dict[str, Any]]] = None,
    entities: Optional[List[Dict[str, Any]]] = None,
) -> Dict[str, Any]:
    """Build v1-compatible parse data for downstream command processing."""
    return {
        TEXT: text,
        INTENT: {INTENT_NAME_KEY: None, PREDICTED_CONFIDENCE_KEY: 0.0},
        ENTITIES: entities or [],
        COMMANDS: commands or [],
    }


def command_names_from_parse_data(parse_data: Dict[str, Any]) -> List[str]:
    """Extract command names from v1-shaped parse data."""
    raw_commands = parse_data.get(COMMANDS)
    if not isinstance(raw_commands, list):
        return []

    command_names: List[str] = []
    for item in raw_commands:
        if not isinstance(item, dict):
            continue
        command_name = cast(Dict[str, Any], item).get("command")
        if isinstance(command_name, str):
            command_names.append(command_name)
    return command_names
